import heapq

def dijkstra(g, s):
    dist = {v: float("inf") for v in g}
    dist[s] = 0
    done = set()
    pq = [(0, s)]
    while pq:
        d, u = heapq.heappop(pq)
        if u in done:
            continue
        done.add(u)
        for v, w in g[u]:
            if v not in done and d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(pq, (dist[v], v))
    return dist

