import heapq

def prim(g, s):
    seen, total, picked = {s}, 0, []
    pq = [(w, v) for v, w in g[s]]
    heapq.heapify(pq)
    while pq and len(seen) < len(g):
        w, v = heapq.heappop(pq)
        if v in seen:
            continue
        seen.add(v)
        total += w
        picked.append(w)
        for x, wx in g[v]:
            if x not in seen:
                heapq.heappush(pq, (wx, x))
    return picked, total

