def delete(t, k):
    if t is None:
        return None
    if k < t.k:
        t.l = delete(t.l, k)
    elif k > t.k:
        t.r = delete(t.r, k)
    else:
        if t.l is None:
            return t.r
        if t.r is None:
            return t.l
        s = t.r
        while s.l:
            s = s.l
        t.k = s.k
        t.r = delete(t.r, s.k)
    return t

