from collections import deque

def max_flow(edges, s, t):
    cap, adj = {}, {}
    for u, v, c in edges:
        cap[(u, v)] = cap.get((u, v), 0) + c
        cap.setdefault((v, u), 0)            # reverse (residual) edge
        adj.setdefault(u, set()).add(v)
        adj.setdefault(v, set()).add(u)
    flow = 0
    while True:
        parent, q = {s: None}, deque([s])    # BFS = Edmonds-Karp
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in parent and cap[(u, v)] > 0:
                    parent[v] = u
                    q.append(v)
        if t not in parent:
            return flow
        b, v = float("inf"), t
        while parent[v] is not None:
            b, v = min(b, cap[(parent[v], v)]), parent[v]
        v = t
        while parent[v] is not None:
            cap[(parent[v], v)] -= b
            cap[(v, parent[v])] += b
            v = parent[v]
        flow += b

E = [("s", "a", 2), ("s", "b", 2), ("a", "b", 2), ("a", "t", 2), ("b", "t", 2)]
print(max_flow(E, "s", "t"))

import heapq

def min_rooms(meetings):
    ends = []                       # min-heap of end times of busy rooms
    for start, end in sorted(meetings):
        if ends and ends[0] <= start:
            heapq.heapreplace(ends, end)   # reuse the room that frees first
        else:
            heapq.heappush(ends, end)      # open a new room
    return len(ends)

print(min_rooms([(0, 30), (5, 10), (15, 20), (25, 40), (35, 45)]))

