    for i in range(n):
        j = 1
        while j < n:
            j *= 2
            steps += 1
    return steps

import heapq

def kth_largest(a, k):
    h = []
    for x in a:
        heapq.heappush(h, x)
        if len(h) > k:
            heapq.heappop(h)
    return h[0]

