def total(a):
    if not a:
        return 0
    return a[0] + total(a[1:])

def lis(a):
    best = [1] * len(a)
    for i in range(len(a)):
        for j in range(i):
            if a[j] < a[i]:
                best[i] = max(best[i], best[j] + 1)
    return best

